/* Generated by generate-screen-parity-assets.sh from the original vectors. */
static const struct {
  const char *name;
  const lv_image_dsc_t *image;
  weather_icon_geometry_t geometry;
} weather_icons[] = {
  { "freezing-rain", &wac_weather_freezing_rain, { 400, 84, 76 } },
  { "hail", &wac_weather_hail, { 400, 86, 61 } },
  { "ice", &wac_weather_ice, { 400, 88, 75 } },
  { "wind", &wac_weather_wind, { 400, 80, 90 } },
  { "tornado", &wac_weather_tornado, { 400, 90, 68 } },
  { "clear-day", &weather_icon_clear_day, { 400, 57, 56 } },
  { "clear-night", &weather_icon_clear_night, { 400, 120, 99 } },
  { "cloudy", &weather_icon_cloudy, { 400, 85, 127 } },
  { "fog", &weather_icon_fog, { 400, 86, 62 } },
  { "partlycloudy-day", &weather_icon_partlycloudy_day, { 400, 76, 94 } },
  { "partlycloudy-night", &weather_icon_partlycloudy_night, { 400, 100, 83 } },
  { "rain", &weather_icon_rain, { 400, 84, 76 } },
  { "showers-day", &weather_icon_showers_day, { 400, 57, 50 } },
  { "showers-night", &weather_icon_showers_night, { 400, 86, 51 } },
  { "rain-snow", &weather_icon_sleet, { 400, 86, 61 } },
  { "snow", &weather_icon_snow, { 400, 87, 71 } },
  { "thunderstorm", &weather_icon_thunderstorm, { 400, 87, 71 } },
  { "thundersnow", &weather_icon_thundersnow, { 400, 87, 71 } },
};

const lv_image_dsc_t *weather_icon_image_for_name(const char *icon_name)
{
  const char *resolved_name = weather_icon_name_or_fallback(icon_name);
  for (size_t i = 0; i < sizeof(weather_icons) / sizeof(weather_icons[0]); ++i) {
    if (strcmp(resolved_name, weather_icons[i].name) == 0) return weather_icons[i].image;
  }
  return NULL;
}

const lv_image_dsc_t *weather_icon_image_for_snapshot(const app_weather_snapshot_t *weather)
{
  return weather && weather->valid ? weather_icon_image_for_name(weather->icon_name) : NULL;
}

const weather_icon_geometry_t *weather_icon_geometry_for_image(const lv_image_dsc_t *image)
{
  for (size_t i = 0; i < sizeof(weather_icons) / sizeof(weather_icons[0]); ++i) {
    if (image == weather_icons[i].image) return &weather_icons[i].geometry;
  }
  return NULL;
}
